 ownerpaths=['wiki/research/web-addons-swapper-static.md','wiki/research/helper-launch-live-side.md','wiki/research/sources/ableton-live-12.4.3.md','wiki/specs/delivery-recovery-workflows.md','wiki/research/delivery-recovery-workflows.md','analysis/ableton-live-12.4.3/full-spec-v1/delivery-recovery/manifest-author-r1.json','analysis/ableton-live-12.4.3/full-spec-v1/reviews/delivery-recovery-workflows-review.json']
