 sources=dict(target='Ableton Live 12 Suite 12.4.3 (2026-07-07_e3d8be4d07), selected retained macOS arm64 paths only',origin_capture_date='2026-10-17',origin_utc=None,new_capture=False,origin_manifest=str((H/'manifest.json').relative_to(ROOT)),original_helper_slice=raw,availability='Original helper and three selected bytecode files present; exact raw hashes verified. Retained static evidence present. No original executed/imported; full Live fat not newly rehashed.',pins=inherited+rawpins+owners)
 counts=dict(requirements=len(requirements),provenance=dict(Counter(r['provenance'] for r in requirements)),cases=len(cases),evidence_entries=len(evidence),all_target_unknown=True,executed=0,semantic_complete=0)
